using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class GroundFloorFinalInspect {
 public static string Read(){var scene=SceneManager.GetActiveScene();var map=scene.GetRootGameObjects().Single(g=>g.name=="MyeongjiMap");var lots=(JArray)JObject.Parse(File.ReadAllText("Docs/MapLayout/Myeongji/layout.json"))["lots"];var result=new List<object>();foreach(var lot in lots.Where(v=>"FGH".Contains(((string)v[0]).Substring(0,1)))){string id=(string)lot[0];int rot=(int)lot[7];Vector3 normal=rot==0?Vector3.back:rot==180?Vector3.forward:rot==90?Vector3.right:Vector3.left;Vector3 u=Mathf.Abs(normal.z)>.5f?Vector3.right:Vector3.forward;var r=map.GetComponentsInChildren<MeshRenderer>().Single(x=>x.name=="AB01_"+id+".001");float edge=Vector3.Dot(r.bounds.center,normal)+Mathf.Abs(Vector3.Dot(r.bounds.extents,normal));var m=r.GetComponent<MeshFilter>().sharedMesh;var vs=m.vertices.Select(p=>r.transform.TransformPoint(p)).ToArray();var faces=new List<(int sub,float d,float lo,float hi,float bottom,float top)>();for(int s=0;s<m.subMeshCount;s++){var idx=m.GetTriangles(s);for(int i=0;i<idx.Length;i+=3){var a=vs[idx[i]];var b=vs[idx[i+1]];var c=vs[idx[i+2]];var n=Vector3.Cross(b-a,c-a).normalized;if(Vector3.Dot(n,normal)<.95f||Mathf.Min(a.y,Mathf.Min(b.y,c.y))>=3.2f)continue;float d=Vector3.Dot((a+b+c)/3,normal)-edge;if(d< -1.5f)continue;faces.Add((s,Mathf.Round(d*100)/100,Mathf.Min(Vector3.Dot(a,u),Mathf.Min(Vector3.Dot(b,u),Vector3.Dot(c,u))),Mathf.Max(Vector3.Dot(a,u),Mathf.Max(Vector3.Dot(b,u),Vector3.Dot(c,u))),Mathf.Min(a.y,Mathf.Min(b.y,c.y)),Mathf.Max(a.y,Mathf.Max(b.y,c.y))));}}
 result.Add(new{id,rot,kind=(string)lot[1],edge,min=r.bounds.min.ToString(),max=r.bounds.max.ToString(),mats=r.sharedMaterials.Select(x=>x.name),faces=faces.GroupBy(f=>new{f.sub,f.d}).Select(g=>new{mat=r.sharedMaterials[g.Key.sub].name,depth=g.Key.d,lo=g.Min(f=>f.lo),hi=g.Max(f=>f.hi),bottom=g.Min(f=>f.bottom),top=g.Max(f=>f.top)})});}
 var json=JsonConvert.SerializeObject(new{scene=scene.path,dirty=scene.isDirty,result},Formatting.Indented);File.WriteAllText("Docs/MapLayout/Myeongji/ground_floor_final_inspect.json",json);return "E facade inspection saved: "+result.Count;}}


